const c=require('./common');
(async()=>{try{if(process.env.GITHUB_REF?.includes('/pull/')){c.log('untrusted pull request: save skipped');return}let repo=c.input('repository'),key=c.input('key'),a=c.makeArchive(),hash=c.digest(a.file),name=hash.slice(7)+'.tar.zst',x=await c.object(repo,hash);if(!x){let r=(await c.assets(repo)).release;try{await c.upload(r.upload_url.replace('{?name,label}',`?name=${encodeURIComponent(name)}`),a.file,name,'application/zstd');c.log(`uploaded object ${hash}`)}catch(e){if(e.status!==422)throw e;c.log(`deduplicated object ${hash}`)}}else c.log(`object already exists: ${hash}`);await c.setRef(repo,key,hash);let f=process.env.GITHUB_OUTPUT;if(f)require('fs').appendFileSync(f,`content-hash=${hash}\ncache-size=${require('fs').statSync(a.file).size}\n`);console.log(`Cache saved: ${key} -> ${hash}`)}catch(e){c.fail(e)}})();
